"""The code map (B29): a map of any codebase, generated by code from the repository and its profile
(`vallum/project.yaml`). Agents read it before planning, writing, reviewing or fixing. Never written by an AI.

Readers are pluggable: Python uses the syntax tree; JavaScript, TypeScript, Go and Java use patterns; any other
file is listed by name. Output is deterministic (sorted, no timestamps) so a unit test can keep it fresh.
"""

import ast
import fnmatch
import re
from pathlib import Path

import yaml

GENERIC_ROUTES = [
    r"\b(?:app|router|api|server)\.(get|post|put|patch|delete)\(\s*['\"]([^'\"]+)['\"]",   # Express, Fastify
    r"@(Get|Post|Put|Patch|Delete)Mapping\(\s*(?:value\s*=\s*)?\"([^\"]+)\"",                # Spring
    r"\b(?:r|mux|router)\.(?:HandleFunc|Handle)\(\s*\"([^\"]+)\"",                           # Go net/http
]
PY_ROUTE_METHODS = {"get", "post", "put", "patch", "delete", "route", "api_route"}
EXT_LANG = {".py": "python", ".js": "javascript", ".mjs": "javascript", ".cjs": "javascript", ".ts": "typescript",
            ".tsx": "typescript", ".go": "go", ".java": "java", ".kt": "kotlin", ".rb": "ruby"}


def load_profile(root: Path) -> dict:
    path = root / "vallum" / "project.yaml"
    if not path.exists():
        raise SystemExit(f"no profile at {path}")
    return yaml.safe_load(path.read_text(encoding="utf-8")) or {}


def _ignored(rel: str, ignore: list[str]) -> bool:
    parts = rel.split("/")
    for pat in ignore:
        if fnmatch.fnmatch(rel, pat) or fnmatch.fnmatch(rel, pat.rstrip("/") + "/*") or pat in parts:
            return True
        if "/" in pat and rel.startswith(pat.rstrip("/") + "/"):
            return True
    return False


def files_under(root: Path, dirs: list[str], ignore: list[str]) -> list[str]:
    out = []
    for d in dirs:
        base = root / d
        if base.is_file():
            out.append(d)
            continue
        for p in sorted(base.rglob("*")) if base.exists() else []:
            rel = p.relative_to(root).as_posix()
            if p.is_file() and not _ignored(rel, ignore):
                out.append(rel)
    return sorted(set(out))


# ------------------------------------------------------------------ readers
def read_python(text: str, profile: dict) -> dict:
    out = {"functions": [], "classes": [], "routes": []}
    try:
        tree = ast.parse(text)
    except SyntaxError as exc:
        return {**out, "error": f"syntax error line {exc.lineno}"}
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if not node.name.startswith("_"):
                args = [a.arg for a in node.args.args if a.arg not in ("self", "cls")]
                out["functions"].append(f"{node.name}({', '.join(args)}) :{node.lineno}")
            for dec in node.decorator_list:
                if isinstance(dec, ast.Call) and isinstance(dec.func, ast.Attribute) and dec.func.attr in PY_ROUTE_METHODS:
                    if dec.args and isinstance(dec.args[0], ast.Constant) and isinstance(dec.args[0].value, str):
                        method = dec.func.attr.upper() if dec.func.attr not in ("route", "api_route") else "ANY"
                        out["routes"].append(f"{method} {dec.args[0].value} -> {node.name}()")
        elif isinstance(node, ast.ClassDef) and not node.name.startswith("_"):
            methods = [n.name for n in node.body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
                       and not n.name.startswith("_")]
            out["classes"].append(f"{node.name}" + (f" [{', '.join(methods)}]" if methods else "") + f" :{node.lineno}")
    return out


_JS_FUNCS = [r"^\s*export\s+(?:default\s+)?(?:async\s+)?function\s+(\w+)\s*\(([^)]*)\)",
             r"^\s*(?:export\s+)?(?:const|let)\s+(\w+)\s*=\s*(?:async\s*)?\(([^)]*)\)\s*=>",
             r"^\s*(?:async\s+)?function\s+(\w+)\s*\(([^)]*)\)",
             r"^\s*func\s+(?:\([^)]*\)\s*)?([A-Z]\w*)\s*\(([^)]*)\)",
             r"^\s*public\s+(?:static\s+)?[\w<>\[\]]+\s+(\w+)\s*\(([^)]*)\)"]
_CLASSES = r"^\s*(?:export\s+)?(?:default\s+)?(?:public\s+)?(?:abstract\s+)?class\s+(\w+)"


def read_generic(text: str, profile: dict) -> dict:
    out = {"functions": [], "classes": [], "routes": []}
    seen = set()
    for i, line in enumerate(text.splitlines(), 1):
        for pat in _JS_FUNCS:
            m = re.search(pat, line)
            if m and m.group(1) not in seen and not m.group(1).startswith("_"):
                seen.add(m.group(1))
                out["functions"].append(f"{m.group(1)}({m.group(2).strip()}) :{i}")
                break
        m = re.search(_CLASSES, line)
        if m:
            out["classes"].append(f"{m.group(1)} :{i}")
    out["routes"] = find_routes(text, profile, generic=True)
    return out


def find_routes(text: str, profile: dict, generic: bool) -> list[str]:
    pats = list((profile.get("routes") or {}).get("patterns") or [])
    if generic:
        pats += GENERIC_ROUTES
    found = []
    for pat in pats:
        for m in re.finditer(pat, text):
            groups = [g for g in m.groups() if g]
            if len(groups) >= 2:
                found.append(f"{groups[0].upper()} {groups[1]}")
            elif groups:
                found.append(f"ANY {groups[0]}")
    return sorted(set(found))


READERS = {"python": read_python}


def read_file(root: Path, rel: str, profile: dict) -> dict | None:
    lang = EXT_LANG.get(Path(rel).suffix)
    if not lang:
        return None
    text = (root / rel).read_text(encoding="utf-8", errors="replace")
    info = READERS.get(lang, read_generic)(text, profile)
    info["lang"], info["lines"] = lang, text.count("\n") + 1
    return info


def count_tests(text: str) -> int:
    return len(re.findall(r"^\s*def test_\w+|^\s*(?:it|test)\(\s*['\"]|^\s*func Test\w+|@Test\b", text, re.M))


# ------------------------------------------------------------------ cards
def load_cards(root: Path, overrides: dict | None = None) -> list[dict]:
    """The Feature Cards; `overrides` maps a card path to the text it will have (housekeeping drops watch blocks)."""
    cards, overrides = [], overrides or {}
    for p in sorted((root / "promises" / "features").glob("*.yaml")) if (root / "promises" / "features").exists() else []:
        rel = p.relative_to(root).as_posix()
        try:
            card = yaml.safe_load(overrides[rel] if rel in overrides else p.read_text(encoding="utf-8")) or {}
        except yaml.YAMLError:
            continue
        ids = {t: [x.get("id") for x in (card.get("promises") or {}).get(t) or []] for t in (card.get("promises") or {})}
        cards.append({"path": p.relative_to(root).as_posix(), "feature": card.get("feature"), "tier": card.get("tier"),
                      "kind": card.get("kind"), "priority": card.get("priority"), "flag": card.get("flag"),
                      "routes": (card.get("owns") or {}).get("routes") or [], "files": (card.get("owns") or {}).get("files") or [],
                      "promises": ids, "watch": [w.get("id") for w in card.get("watch") or []]})
    return cards


# ------------------------------------------------------------------ render
def generate(root: Path, card_overrides: dict | None = None) -> str:
    root = Path(root)
    profile = load_profile(root)
    ignore = list(profile.get("ignore") or [])
    src = files_under(root, list(profile.get("source_dirs") or []), ignore)
    tests = files_under(root, list(profile.get("test_dirs") or []), ignore)
    cards = load_cards(root, card_overrides)
    owner = {}
    for c in cards:
        for f in c["files"]:
            owner[f] = c["feature"]
        for r in c["routes"]:
            owner[r] = c["feature"]

    lines = [f"# Code map: {profile.get('name', root.name)}", "",
             "_Generated by code from the repository and `vallum/project.yaml` (`python -m vallum.codemap`). "
             "Never edit by hand; it is refreshed after every release._", ""]
    if profile.get("description"):
        lines += [profile["description"], ""]
    feat = profile.get("feature") or {}
    cmds = profile.get("commands") or {}
    lines += ["## Layout", "",
              f"- Language: {profile.get('language', '?')}" + (f" ({profile['framework']})" if profile.get("framework") else ""),
              f"- Source: {', '.join(f'`{d}`' for d in profile.get('source_dirs') or [])}; tests: "
              f"{', '.join(f'`{d}`' for d in profile.get('test_dirs') or [])}"]
    if feat:
        lines.append(f"- A feature lives in `{feat.get('module', '?')}`, its tests in `{feat.get('test', '?')}`, "
                     f"its Feature Card in `{feat.get('card', '?')}`")
    if profile.get("entry_points"):
        lines.append(f"- Entry points: {', '.join(f'`{e}`' for e in profile['entry_points'])}")
    if profile.get("never_edit"):
        lines.append(f"- Never edited by a feature: {', '.join(f'`{e}`' for e in profile['never_edit'])}")
    if cmds:
        lines.append(f"- Test command: `{cmds.get('test', '?')}`; health check: `{cmds.get('health', '?')}`")
    lines.append("")

    if cards:
        lines += ["## Features (from Feature Cards)", "", "| Feature | Tier | Kind | Routes | Files | Flag | Promises |",
                  "|---|---|---|---|---|---|---|"]
        for c in sorted(cards, key=lambda c: (c["feature"] or "")):
            proms = "; ".join(f"{t}: {', '.join(i for i in ids if i)}" for t, ids in sorted(c["promises"].items()) if ids)
            if c["watch"]:
                proms += f"; watch: {', '.join(c['watch'])}"
            lines.append(f"| {c['feature']} | {c['tier']} | {c['kind']} | {'<br>'.join(f'`{r}`' for r in c['routes'])} | "
                         f"{'<br>'.join(f'`{f}`' for f in c['files'])} | {c['flag'] or '-'} | {proms} |")
        lines.append("")

    all_routes = []
    lines += ["## Modules", ""]
    for rel in src:
        info = read_file(root, rel, profile)
        if info is None:
            lines.append(f"- `{rel}`")
            continue
        tag = f" · feature **{owner[rel]}**" if rel in owner else ""
        lines.append(f"### `{rel}` ({info['lang']}, {info['lines']} lines){tag}")
        if info.get("error"):
            lines.append(f"- {info['error']}")
        for r in info["routes"]:
            all_routes.append((r.split(" -> ")[0], rel))
            lines.append(f"- route `{r}`")
        for c in info["classes"]:
            lines.append(f"- class `{c}`")
        for f in info["functions"]:
            lines.append(f"- def `{f}`")
        lines.append("")

    if all_routes:
        lines += ["## Routes", "", "| Route | Defined in | Feature |", "|---|---|---|"]
        for route, rel in sorted(set(all_routes)):
            lines.append(f"| `{route}` | `{rel}` | {owner.get(route) or owner.get(rel) or '-'} |")
        lines.append("")

    if tests:
        lines += ["## Tests", ""]
        for rel in tests:
            if EXT_LANG.get(Path(rel).suffix):
                n = count_tests((root / rel).read_text(encoding="utf-8", errors="replace"))
                lines.append(f"- `{rel}`: {n} test(s)")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def output_path(root: Path) -> Path:
    profile = load_profile(Path(root))
    return Path(root) / ((profile.get("docs") or {}).get("codemap") or "docs/vallum/CODEMAP.md")
